import os
import requests

token = os.environ["SPOTIFY_ACCESS_TOKEN"]
headers = {"Authorization": f"Bearer {token}"}
base_url = "https://api.spotify.com/v1"

response = requests.get(
    f"{base_url}/me/playlists",
    headers=headers,
    params={"limit": 1, "offset": 0},
)
response.raise_for_status()
playlists = response.json().get("items", [])

if playlists:
    playlist_id = playlists[0]["id"]
    tracks_url = f"{base_url}/playlists/{playlist_id}/tracks"
    params = {"limit": 100}
    items_to_remove = []

    while tracks_url:
        response = requests.get(
            tracks_url,
            headers=headers,
            params=params,
        )
        response.raise_for_status()
        page = response.json()
        items_to_remove.extend(
            {"uri": item["track"]["uri"]}
            for item in page.get("items", [])
            if item.get("track") and item["track"].get("uri")
        )
        tracks_url = page.get("next")
        params = None

    for start in range(0, len(items_to_remove), 100):
        response = requests.delete(
            f"{base_url}/playlists/{playlist_id}/tracks",
            headers=headers,
            json={"tracks": items_to_remove[start:start + 100]},
        )
        response.raise_for_status()
